"""Contact sheet rows for substitute teachers."""

from typing import List, Sequence

from rosterkit.models import Student


# ---
def contact_rows(students: Sequence[Student]) -> List[str]:
    """Text rows of name, section and email, by name."""
    if not students:
        raise ValueError("no students to list")
    for student in students:
        if not (student.email or "").strip():
            raise ValueError(
                f"no email for {student.display_name}"
            )
    ordered = sorted(
        students,
        key=lambda item: (
            item.display_name.lower(),
            item.student_id
        ),
    )
    name_width = max(len(i.display_name) for i in ordered)
    sect_width = max(len(i.section) for i in ordered)
    return [
        f"{item.display_name:<{name_width}}  "
        f"{item.section:<{sect_width}}  "
        f"{item.email.strip()}"
        for item in ordered
    ]
EOF
cat > tests/test_contacts.py <<'EOF'
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def make(ident, last, first, sect, mail="x@y.org"):
    return Student(ident, last, first, sect, mail)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name(self):
        rows = contact_rows(
            [
                make("2", "Young", "Zed", "B", "z@y.org"),
                make("1", "Adams", "Amy", "A", "a@y.org"),
            ]
        )
        self.assertEqual(
            rows,
            [
                "Adams, Amy  A  a@y.org",
                "Young, Zed  B  z@y.org",
            ],
        )

    def test_columns_line_up(self):
        rows = contact_rows(
            [
                make("1", "Li", "Jo", "A", "j@y.org"),
                make("2", "Hernandez", "Ana", "AB", "a@y.org"),
            ]
        )
        self.assertEqual(
            rows[0].index("a@y.org"),
            rows[1].index("j@y.org"),
        )

    def test_missing_email_names_student(self):
        with self.assertRaises(ValueError) as caught:
            contact_rows([make("1", "Li", "Jo", "A", None)])
        self.assertIn("Li, Jo", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ValueError):
            contact_rows([make("1", "Li", "Jo", "A", "  ")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
